#!/usr/bin/env node
// Build the claude.ai/design project payload from the vanilla catalog runtime.
//
// The catalog is framework-neutral: `catalog-runtime/italki-ui.js` installs
// `window.ITalkiUI`, a set of ~175 render functions that return HTML strings,
// and `catalog-runtime/contracts.js` installs `window.ITalkiUIContracts`, which
// the runtime asserts every prop against. claude.ai/design renders designs
// through React, so this script emits React wrappers around those renderers
// (the "custom-vanilla-react" shape) plus one static preview card per
// component, generated by actually calling the renderer.
//
// This script exists because the previous upload was produced ad hoc and never
// committed — when it had to be reproduced, it could not be. Keep it committed.
//
//   node maintenance/scripts/build-ds-project.mjs --out maintenance/ds-project
//
// Output layout (what the app's self-check consumes):
//   _ds_bundle.js      IIFE → window.ItalkiUI (React wrappers)
//   _ds_bundle.css     the vanilla stylesheet
//   styles.css         @imports the closure a rendered design receives
//   tokens/tokens.css  the token layer
//   components/<slug>/<Name>/<Name>.{html,jsx,d.ts,prompt.md}
//   _ds_needs_recompile

import { mkdirSync, readFileSync, writeFileSync, rmSync, existsSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';

const argv = process.argv.slice(2);
const flag = (n, d) => { const i = argv.indexOf(`--${n}`); return i < 0 ? d : argv[i + 1]; };
const REPO = resolve(flag('repo', '.'));
const OUT = resolve(flag('out', 'maintenance/ds-project'));
const RUNTIME = join(REPO, 'catalog-runtime');

// ── load the vanilla runtime under a stub window ──────────────────────────
// The renderers only build strings; the interactive handlers touch
// global.document, which stays undefined and is never called here.
const contractsSrc = readFileSync(join(RUNTIME, 'contracts.js'), 'utf8');
/* The runtime verifies a named icon against this, so the bundle has to carry
   it: without the manifest a name still resolves, but to the library root,
   which is wrong for the 16px set and unchecked for everything else. */
const iconManifestSrc = readFileSync(join(RUNTIME, 'icon-manifest.js'), 'utf8');
const runtimeSrc = readFileSync(join(RUNTIME, 'italki-ui.js'), 'utf8');
const sandbox = {};
sandbox.window = sandbox;
new Function('window', 'global', `${contractsSrc}\n${runtimeSrc}`)(sandbox, sandbox);
const UI = sandbox.ITalkiUI;
const CONTRACTS = sandbox.ITalkiUIContracts.components;
if (!UI) throw new Error('window.ITalkiUI was not installed — check catalog-runtime/italki-ui.js');

// ── the component set, preserving the previously published names/groups ───
// name: card + export name · fn: runtime renderer · key: contract key
// group: display group the DS pane shows · slug: path segment (kept identical
// to the previous upload so card URLs and the picker stay stable).
// The Design pane groups by each card's `@dsCard group="…"` marker. Those
// groups used to be invented here — Actions/Forms/… — and 28 of the 52
// components landed in a section the Catalog does not put them in: Tabs under
// Navigation instead of Data Display, Stepper under Feedback instead of Layout,
// Dropdown menu under Actions instead of Overlays. Read the Catalog's own
// taxonomy instead, so the two cannot disagree.
//
// Paths keep their original slug: the pane indexes by the marker, not the path,
// and re-slugging would fork every card URL while the old files stayed behind.
const CATALOG_HTML = readFileSync(join(REPO, 'index.html'), 'utf8');
const catalogTaxonomy = () => {
  const start = CATALOG_HTML.indexOf('const groups = [');
  const end = CATALOG_HTML.indexOf('const navigationComponents', start);
  if (start < 0 || end < 0) throw new Error('Could not find the Catalog group tables in index.html');
  const table = new Map();
  let rank = 0;
  const take = (title, list) => {
    for (const entry of list.split(';')) {
      const label = entry.split('|')[0].trim();
      if (label) table.set(label.toLowerCase(), { group: title, rank: rank++ });
    }
  };
  const groupRule = /title:\s*"([^"]+)"[\s\S]{0,400}?parse\("([^"]*)"\)/g;
  for (const m of CATALOG_HTML.slice(start, end).matchAll(groupRule)) {
    if (m[1] === 'Principles' || m[1] === 'Foundation') continue;
    take(m[1], m[2]);
  }
  const nav = CATALOG_HTML.match(/const navigationComponents = parse\("([^"]*)"\)/);
  if (nav) take('Navigation', nav[1]);
  if (table.size < 40) throw new Error(`Catalog taxonomy looked wrong: ${table.size} entries`);
  return table;
};
const TAXONOMY = catalogTaxonomy();

